using System.IO.Pipes; using System.Text; using System.Text.Json; using System.Windows; using System.Windows.Controls;
namespace IracingLiveCoach.ControlCenter;
public partial class MainWindow : Window { private string _key="standings"; public MainWindow(){InitializeComponent();} private void SelectWidget(object s,RoutedEventArgs e){_key=(string)((Button)s).Tag;Title.Text=_key.ToUpperInvariant();Send();} private void Changed(object s,RoutedEventArgs e)=>Send(); private async void Send(){try{using var pipe=new NamedPipeClientStream(".","IracingLiveCoach.V3.Control",PipeDirection.Out);await pipe.ConnectAsync(100);var json=JsonSerializer.Serialize(new{widget=_key,visible=Visible.IsChecked==true,locked=Locked.IsChecked==true,opacity=Opacity.Value,scale=Scale.Value});await pipe.WriteAsync(Encoding.UTF8.GetBytes(json+"\n"));}catch{}}}
